contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run() public payable {
        require(true);

        // Setup: create the observable state this rule depends on.
        c.setEnforcement(false);

        // Read the before-value through the public getter (enforceLimitsActive is public).
        bool beforeVal = c.enforceLimitsActive(address(this));

        // Deciding call: set enforcement to true for the caller (this test contract).
        c.setEnforcement(true);

        // Read the after-value through the same public getter.
        bool afterVal = c.enforceLimitsActive(address(this));

        // General rule: calling setEnforcement(true) always makes the stored flag true
        // for msg.sender, regardless of its previous value.
        assert(beforeVal == false && afterVal == true);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run() public payable {
        require(true);

        // Setup: ensure configured is true so enforceTolerance does not early-return on configured().
        c.endConfiguration();

        // Call setEnforcement(true) for this test contract.
        c.setEnforcement(true);

        // Now enforceTolerance should not return early and should enforce the tolerance rule.
        // Use v1 = v2 to pass the tolerance check without relying on security parameters.
        uint256 v1 = 1;
        uint256 v2 = 1;

        bool reverted;
        try c.enforceTolerance(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: after setEnforcement(true), enforceTolerance(1,1) does not revert.
        assert(!reverted);
    }

    receive() external payable {}
}

