contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address asset, uint256 amount, uint256 unlockTime, bool assetBurnable) public {
        // Configure the DAO and flash governor so onlySuccessfulProposal passes via configured == false.
        // c.DAO() is a public getter inherited from Governable; configured() is also public.
        require(c.DAO() != address(0) || true);

        // Read before values (they may be arbitrary until configureFlashGovernance is called).
        (address beforeAsset, uint256 beforeAmount, uint256 beforeUnlockTime, bool beforeBurnable) = c.flashGovernanceConfig();

        // The deciding call: configure flash governance. Under a fresh deployment, configured == false,
        // so onlySuccessfulProposal passes for any sender. This is a top-level state-changing call.
        bool reverted;
        try c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values.
        (address afterAsset, uint256 afterAmount, uint256 afterUnlockTime, bool afterBurnable) = c.flashGovernanceConfig();

        // General rule: after a successful configureFlashGovernance call, the public getter must
        // return exactly the parameters passed in. If the call reverted, the getter must remain unchanged.
        assert(
            (!reverted && afterAsset == asset && afterAmount == amount && afterUnlockTime == unlockTime && afterBurnable == assetBurnable) ||
            (reverted && afterAsset == beforeAsset && afterAmount == beforeAmount && afterUnlockTime == beforeUnlockTime && afterBurnable == beforeBurnable)
        );
    }
}

