        c = _c;
    }

    function run(uint8 maxGovernanceChangePerEpoch, uint256 epochSize, uint8 changeTolerance) public payable {
        require(changeTolerance < 100, "precondition: tolerance must be < 100 to satisfy config require");

        c.configureSecurityParameters(maxGovernanceChangePerEpoch, epochSize, changeTolerance);

        (uint256 epochSizeOut, , uint8 changeToleranceOut) = c.security();

        assert(changeToleranceOut == changeTolerance && changeToleranceOut < 100);
