contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable,
        address target,
        uint256 epochSize,
        uint8 changeTolerance
    ) public payable {
        // Configure flash governance. Requires the test contract to be able to call this; it will
        // revert unless c is already configured and the caller is authorized, so we wrap and only
        // proceed if configuration succeeded.
        bool configuredOk;
        try c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable) {
            configuredOk = true;
        } catch {
            configuredOk = false;
        }

        if (!configuredOk) {
            assert(true);
            return;
        }

        bool securityOk;
        try c.configureSecurityParameters(1, epochSize, changeTolerance) {
            securityOk = true;
        } catch {
            securityOk = false;
        }

        if (!securityOk) {
            assert(true);
            return;
        }

        bool decisionOk;
        try c.assertGovernanceApproved(address(this), target, true) {
            decisionOk = true;
        } catch {
            decisionOk = false;
        }

        if (!decisionOk) {
            assert(true);
            return;
        }

        // After a successful decision, the pending flash decision for (target, sender) should
        // record the configured asset and amount, and the contract should hold at least `amount`
        // of the asset (transferred in by assertGovernanceApproved).
        (uint256 recordedAmount, uint256 recordedUnlockTime, address recordedAsset, bool recordedBurnable) =
            c.pendingFlashDecision(target, address(this));

        assert(
            recordedAmount == amount &&
            recordedAsset == asset &&
            recordedBurnable == assetBurnable &&
            recordedUnlockTime >= block.timestamp &&
            IERC20(asset).balanceOf(address(c)) >= amount
        );
    }

    receive() external payable {}
}

