contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newDao, address caller) public payable {
        require(newDao != address(0), "new DAO must be nonzero");

        address originalDao = c.DAO();
        bool configuredBefore = c.configured();

        // Try to replace the DAO from an arbitrary non-DAO caller.
        // The call goes through msg.sender = address(this), which is neither
        // the current DAO nor necessarily the original DAO unless the test is deployed by it.
        bool reverted;
        if (msg.sender != originalDao) {
            try c.setDAO(newDao) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // The DAO can be changed only if it was unconfigured or if the caller is the DAO.
        // For an unconfigured contract, setDAO should succeed regardless of caller.
        // For a configured contract, setDAO should revert for a non-DAO caller.
        bool daoChanged = c.DAO() != originalDao;

        if (!configuredBefore) {
            assert(!reverted && daoChanged);
        } else if (msg.sender != originalDao) {
            assert(reverted && !daoChanged);
        } else {
            assert(!reverted && daoChanged);
        }
    }

    receive() external payable {}
}

