contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address governable, bool isGoverned) public payable {
        require(governable != address(0), "zero address");

        // The caller is this test contract, and c.governed(address(this)) must be true so that
        // setGoverned can be called by a governed address (or DAO).  Because c was deployed by
        // this test, c.DAO() is address(0) at construction and only the DAO can call setGoverned.
        // However, we cannot assume we are DAO. We can, however, take the address that the test
        // contract will use as msg.sender: it is address(this).  The only reliable way to make
        // this test pass is if setGoverned succeeds.  We therefore require that the call does
        // not revert, and then check the public mapping getter.
        //
        // But a simple call c.setGoverned([governable], [isGoverned]) is onlySuccessfulProposal.
        // We cannot set up a successful proposal without external infrastructure.
        // Therefore we use the fact that after the DAO is set to this contract, configured is
        // false, so onlySuccessfulProposal passes for any sender if !configured.
        // c.DAO() is currently address(0) because the constructor of C only called
        // Governable(dao) with the dao argument given to C's constructor; our constructor
        // receives _c already deployed.  So we cannot change DAO here except by calling setDAO.
        // setDAO is public and requires: DAO == address(0) || msg.sender == DAO || !configured.
        // Since DAO is address(0), we can set it to address(this).
        address oldDAO = c.DAO();
        c.setDAO(address(this));

        // Now configured is still false (endConfiguration hasn't been called), so
        // assertSuccessfulProposal passes for any sender.
        address[] memory governables = new address[](1);
        bool[] memory isGovernedArr = new bool[](1);
        governables[0] = governable;
        isGovernedArr[0] = isGoverned;

        c.setGoverned(governables, isGovernedArr);

        // check the mapping value
        bool after = c.governed(governable);

        assert(after == isGoverned);
    }

    receive() external payable {}
}

