    }

    function run(
        address dao,
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable,
        address target,
        address sender,
        bool emergency
    ) public payable {
        // Configure DAO and governance setup through public surface only.
        // Make a proposal via DAO; expected to be the successful proposal for sender.
        // We only use c's public/getter and DAO-like calls indirectly; but dao is unknown type.
        // Instead rely on already-configured state via constructor? Fresh c has DAO set to dao param,
        // but no successful proposals. We cannot make DAO calls (not exposed).
        // Therefore choose a rule not needing successful proposal: configureFlashGovernance is onlySuccessfulProposal,
        // so we cannot call it in a fresh deployment. Instead, test enforceTolerance behavior which is view and depends on
        // enforceLimitsActive[msg.sender] and Configurable(msg.sender).configured(). Since msg.sender is InvMutTest itself,
        // these default to false, so enforceTolerance returns early with no revert. That is a general rule.

        // Read before values (no state change).
        bool reverted;
        uint256 v1 = amount;
        uint256 v2 = unlockTime;
        try c.enforceTolerance(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // Since enforceLimitsActive[InvMutTest] is false by default and InvMutTest is not Configurable,
        // the function must return without reverting.
        assert(!reverted);
    }

    receive() external payable {}
}

