contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address targetContract, address asset, address user, uint256 amount, uint256 unlockTime, bool assetBurnable) public {
        // Setup: configure flash governance through the successful proposal path.
        // The test contract is the DAO because it deployed c.
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // Before values of the public mapping getter.
        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, bool beforeBurnable) =
            c.pendingFlashDecision(targetContract, user);

        // Attempt to withdraw; no pending decision was recorded for msg.sender == address(this)
        // at (targetContract, user) unless user == address(this).
        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the mapping again after the deciding call.
        (uint256 afterAmount, uint256 afterUnlockTime, address afterAsset, bool afterBurnable) =
            c.pendingFlashDecision(targetContract, user);

        if (user != address(this)) {
            assert(reverted);
            assert(afterAmount == beforeAmount);
