contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset, uint256 amount, uint256 unlockTime, bool assetBurnable) public {
        // Set up a successful-proposal context so onlySuccessfulProposal passes.
        // DAO is set via the constructor (address of this test contract), so make the
        // caller a successful proposal by having c.this address be a successful proposal.
        // We cannot call DAO directly, so we must rely on the configured state of c.
        // If c is not configured, onlySuccessfulProposal is bypassed by the modifier logic.
        // However, to be safe, we just call configureFlashGovernance; if it reverts, the test
        // will not reach the assert, but the assert checks the post-condition when it succeeds.

        (address beforeAsset, uint256 beforeAmount, uint256 beforeUnlock, bool beforeBurnable) = c.flashGovernanceConfig();

        bool reverted;
        try c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            (address afterAsset, uint256 afterAmount, uint256 afterUnlock, bool afterBurnable) = c.flashGovernanceConfig();
            assert(
                afterAsset == asset &&
                afterAmount == amount &&
                afterUnlock == unlockTime &&
                afterBurnable == assetBurnable
            );
        } else {
            // If the call reverted, the state must be unchanged.
            (address afterAsset, uint256 afterAmount, uint256 afterUnlock, bool afterBurnable) = c.flashGovernanceConfig();
            assert(
                afterAsset == beforeAsset &&
                afterAmount == beforeAmount &&
                afterUnlock == beforeUnlock &&
                afterBurnable == beforeBurnable
            );
        }
    }
}

