    }

    function run(
        address target,
        address asset,
        uint256 amount,
        uint256 unlockTime
    ) public payable {
        // Configure the flash governance asset, amount, and unlock time.
        c.configureFlashGovernance(asset, amount, unlockTime, false);

        // Ensure the arbitrary unlockTime is not in the future, so that the decision is immediately withdrawable.
        require(unlockTime == 0);

        // Make the flash governance decision. This will transfer `amount` of `asset` from this contract
        // to c, so we must have enough balance and allowance.
        if (amount > 0) {
            require(address(this).balance >= 0);
            IERC20(asset).approve(address(c), amount);
