        uint256 cBalanceBefore = IERC20(asset).balanceOf(address(c));
        c.assertGovernanceApproved(address(this), target, true);
        uint256 cBalanceAfter = IERC20(asset).balanceOf(address(c));

        // The decision must have been recorded and the asset transferred to c.
        assert(cBalanceAfter - cBalanceBefore == amount);

        // Attempt to withdraw the pending governance asset.
        uint256 beforeBalance = IERC20(asset).balanceOf(address(this));
        c.withdrawGovernanceAsset(target, asset);
        uint256 afterBalance = IERC20(asset).balanceOf(address(this));

        // After withdrawal, the caller must receive the exact amount and the pending decision must be cleared.
        (uint256 pendingAmount, uint256 pendingUnlockTime, address pendingAsset, ) =
            c.pendingFlashDecision(target, address(this));

        assert(
            afterBalance - beforeBalance == amount &&
            pendingAmount == 0 &&
            pendingUnlockTime == 0 &&
            pendingAsset == address(0)
        );
    }

    receive() external payable {}
}

