    constructor(C _c) { c = _c; }

    function run(
        address sender,
        address target,
        bool emergency,
        address asset,
        uint256 amount,
        uint256 unlockTime,
        address gov,
        bool isGoverned
    ) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // Configure flash governance: sender must be a successful proposal or !configured.
        // Since freshly deployed, configured is false, so this may still revert if DAO check fails.
        c.configureFlashGovernance(asset, amount, unlockTime, false);

        // Register a possibly governed sender for the target contract; the caller here is this test contract,
        // which must be a successful proposal to pass onlySuccessfulProposal. We cannot control that from here
        // in general; but we can call and catch. We'll rely on the fact that configured is false initially,
        // so some calls are allowed. But setGoverned is onlySuccessfulProposal and may revert if configured
        // and not successful. We'll skip setGoverned and instead call assertGovernanceApproved directly,
        // which has modifier flashEnabled requiring msg.sender == DAO || governed[msg.sender]. Since we are
        // this test contract, and DAO is set in constructor, we are not DAO. governed is empty, so it would
        // revert. To make it callable we need to set governed for this test contract, which requires only
        // successful proposal. We cannot guarantee that. So instead we focus on the revert path: when
        // msg.sender is not authorized, the call must revert, and no state changes.

        uint256 balanceBefore = IERC20(asset).balanceOf(address(c));
        (uint256 pAmountBefore, uint256 pUnlockBefore, address pAssetBefore, bool pBurnableBefore) = c.pendingFlashDecision(target, address(this));

        bool reverted;
        try c.assertGovernanceApproved(address(this), target, emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 pAmountAfter, uint256 pUnlockAfter, address pAssetAfter, bool pBurnableAfter) = c.pendingFlashDecision(target, address(this));
        uint256 balanceAfter = IERC20(asset).balanceOf(address(c));

        // General rule: if the call did not revert, then the pending flash decision for (target, sender)
        // must have been populated with the configured asset and amount, and unlockTime set to at least
        // the configured unlockTime plus block.timestamp (greater than 0), and the contract's asset balance
        // must have increased by exactly the configured amount (or at least not decreased).
        if (!reverted) {
            assert(
                pAssetAfter == asset &&
                pAmountAfter == amount &&
                pAmountAfter > 0 &&
                pUnlockAfter > unlockTime &&
                balanceAfter == balanceBefore + amount
            );
        } else {
            // If it reverted, the pending decision for this tuple must be unchanged.
            assert(
                pAmountAfter == pAmountBefore &&
                pUnlockAfter == pUnlockBefore &&
                pAssetAfter == pAssetBefore &&
                pBurnableAfter == pBurnableBefore &&
                balanceAfter == balanceBefore
            );
        }
    }

    receive() external payable {}
}

contract InvMutTest {
