contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable,
        address sender,
        address target,
        bool emergency
    ) public {
        require(amount > 0, "amount zero");

        // Configure flash governance. Requires onlySuccessfulProposal, and our test contract is the DAO.
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // Record the before state.
        uint256 beforeUnlock;
        uint256 beforeAmount;
        address beforeAsset;
        bool beforeBurnable;
        (beforeAmount, beforeUnlock, beforeAsset, beforeBurnable) = c.flashGovernanceConfig();

        // The deciding call: must succeed or revert deterministically.
        bool reverted;
        try c.assertGovernanceApproved(sender, target, emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post state.
        uint256 afterAmount;
        uint256 afterUnlock;
        address afterAsset;
        bool afterBurnable;
        (afterAmount, afterUnlock, afterAsset, afterBurnable) = c.flashGovernanceConfig();

        // The config getter must be stable regardless of the flash call outcome.
        assert(
            afterAmount == beforeAmount &&
            afterUnlock == beforeUnlock &&
            afterAsset == beforeAsset &&
            afterBurnable == beforeBurnable
        );
    }
}

