contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address[] calldata governables, bool[] calldata isGoverned) public {
        bool lengthMismatch = governables.length != isGoverned.length;
        bool reverted;
        try c.setGoverned(governables, isGoverned) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool allMatch = true;
        bool anyLost = false;
        uint256 n = governables.length < isGoverned.length ? governables.length : isGoverned.length;
        for (uint256 i = 0; i < n; i++) {
            bool actual = c.governed(governables[i]);
            if (actual != isGoverned[i]) allMatch = false;
            if (!actual && isGoverned[i]) anyLost = true;
        }

        assert(
            (lengthMismatch && reverted) ||
            (!lengthMismatch && !reverted && allMatch)
        );
    }
}

