contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] calldata governables, bool[] calldata isGoverned) public {
        require(governables.length == isGoverned.length, "len");
        bool reverted;
        try c.setGoverned(governables, isGoverned) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool allMatch;
        if (!reverted) {
            allMatch = true;
            for (uint256 i = 0; i < governables.length; i++) {
                allMatch = allMatch && (c.governed(governables[i]) == isGoverned[i]);
            }
        }

        assert(reverted || (governables.length == isGoverned.length && allMatch));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] calldata governables, bool[] calldata isGoverned) public {
        bool reverted;
        try c.setGoverned(governables, isGoverned) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (governables.length != isGoverned.length) {
            assert(reverted);
        } else {
            bool allMatch = true;
            for (uint256 i = 0; i < governables.length; i++) {
                allMatch = allMatch && (c.governed(governables[i]) == isGoverned[i]);
            }
            assert(!reverted && allMatch);
        }
    }

    receive() external payable {}
}

