contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address sender, address target, bool emergency) public {
        require(caller != c.DAO(), "caller must not be DAO");
        bool isGoverned = c.governed(caller);
        require(!isGoverned, "caller must not be governed");

        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, bool beforeAssetBurnable) = c.pendingFlashDecision(target, sender);

        bool reverted;
        try c.assertGovernanceApproved(sender, target, emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 afterAmount, uint256 afterUnlockTime, address afterAsset, bool afterAssetBurnable) = c.pendingFlashDecision(target, sender);

        assert(
            reverted &&
            afterAmount == beforeAmount &&
            afterUnlockTime == beforeUnlockTime &&
            afterAsset == beforeAsset &&
            afterAssetBurnable == beforeAssetBurnable
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address sender, address target, bool emergency) public {
        address dao = c.DAO();
        require(caller != dao, "caller must not be DAO");
        require(!c.governed(caller), "caller must not be governed");

        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, bool beforeAssetBurnable) =
            c.pendingFlashDecision(target, sender);

        bool reverted;
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature(
                "assertGovernanceApproved(address,address,bool)",
                sender,
                target,
                emergency
            )
        );
        reverted = !ok;

        (uint256 afterAmount, uint256 afterUnlockTime, address afterAsset, bool afterAssetBurnable) =
            c.pendingFlashDecision(target, sender);

        assert(
            reverted &&
            afterAmount == beforeAmount &&
            afterUnlockTime == beforeUnlockTime &&
            afterAsset == beforeAsset &&
            afterAssetBurnable == beforeAssetBurnable
        );
    }

    receive() external payable {}
}

